// GREEN CHIMP | SISTEMA PACIENTES — ENTRADA WHATSAPP CLOUD API
// Reemplaza el webhook de ManyChat. Lee el payload de Meta (directo o reenviado por el Router).
//
// ÚNICA CONSTANTE: phone_number_id del +52 1 442 680 3532 ("Green Chimp Pruebas", WABA 1041837932183910,
// coexistencia con la app WhatsApp Business). Vacío = acepta cualquier número que llegue a este webhook.
const PHONE_NUMBER_ID_SP = '1300475946479693';

const input = $input.first()?.json || {};
const body = input.body || input;

const value = body?.entry?.[0]?.changes?.[0]?.value || {};
const message = value?.messages?.[0] || null;
const contact = value?.contacts?.[0] || {};
const metadata = value?.metadata || {};
const phone_number_id = String(metadata.phone_number_id || '');

if (PHONE_NUMBER_ID_SP && phone_number_id !== PHONE_NUMBER_ID_SP) return [];

// Webhooks de estado (sent/delivered/read) no traen "messages": se ignoran.
if (!message) return [];

function txt(v) {
  if (v === null || v === undefined) return '';
  const r = String(v).trim();
  const b = r.toLowerCase();
  if (r === '' || r === '[null]' || b === 'null' || b === 'undefined') return '';
  return r;
}

const tipo = txt(message.type);
// Reacciones y eventos de sistema no son mensajes del prospecto.
// "unsupported" (encuestas, ver una vez, etc.) sí se contesta: cae en es_media y se pide texto.
if (['reaction', 'system', 'ephemeral'].includes(tipo)) return [];

const wa_id = txt(contact.wa_id) || txt(message.from);
if (!wa_id) return [];

let texto = '';
let media_id = '';
if (tipo === 'text') {
  texto = txt(message.text?.body);
} else if (tipo === 'button') {
  texto = txt(message.button?.text);
} else if (tipo === 'interactive') {
  texto = txt(message.interactive?.button_reply?.title) || txt(message.interactive?.list_reply?.title);
} else if (['audio', 'image', 'video', 'document', 'sticker'].includes(tipo)) {
  media_id = txt(message[tipo]?.id);
  texto = txt(message[tipo]?.caption);
}

// Audio, imagen, sticker, video, documento, ubicación o contacto SIN texto: se pide que escriba.
const es_media = !texto;
const ETIQUETA = {
  audio: '[nota de voz]', image: '[imagen]', sticker: '[sticker]', video: '[video]',
  document: '[documento]', location: '[ubicación]', contacts: '[contacto]', unsupported: '[mensaje no soportado]'
};

// Atribución Click-to-WhatsApp: solo llega en el primer mensaje que sale del anuncio.
const referral = message.referral || {};

const tsMs = Number(message.timestamp) > 0 ? Number(message.timestamp) * 1000 : Date.now();

return [{
  json: {
    wa_id,
    telefono: '+' + wa_id,
    nombre_perfil: txt(contact.profile?.name),
    tipo_mensaje: tipo,
    texto,
    texto_log: texto || ETIQUETA[tipo] || '[' + tipo + ']',
    es_media,
    media_id,
    message_id: txt(message.id),
    phone_number_id,
    ts_mensaje_ms: tsMs,
    tiene_referral: Boolean(referral.source_id || referral.ctwa_clid),
    ad_id: txt(referral.source_id),
    anuncio_headline: txt(referral.headline) || txt(referral.body),
    ctwa_clid: txt(referral.ctwa_clid),
    referral_tipo: txt(referral.source_type)
  }
}];

// GREEN CHIMP | SISTEMA PACIENTES — CONTEXTO DEL LEAD
// Une el mensaje con el registro de la hoja "leads" y las hojas de configuración.
// Decide (sin IA): origen, agente que contesta y la instrucción de disponibilidad.

const d = $('Extraer Datos').first().json;

function txt(v) {
  if (v === null || v === undefined) return '';
  const r = String(v).trim();
  const b = r.toLowerCase();
  if (r === '' || r === '[null]' || b === 'null' || b === 'undefined') return '';
  return r;
}
const norm = s => txt(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
function filas(nodo) {
  try { return $(nodo).all().map(i => i.json || {}).filter(r => !r.error); } catch (e) { return []; }
}

const leadRow = filas('Leer Lead').find(r => txt(r.wa_id) === d.wa_id) || {};
const existe = Boolean(txt(leadRow.wa_id));
const lead = existe ? leadRow : {};

// ---------------- ORIGEN ----------------
// 1) referral del anuncio → hoja config_anuncios (ad_id → guion)
// 2) palabra clave en el primer mensaje (sin importar mayúsculas ni acentos)
// 3) DIRECTO
const GUIONES = ['PACIENTES', 'SISTEMA', 'CUBETA'];
function palabraClave(texto) {
  const t = norm(texto);
  let mejor = '', pos = Infinity;
  for (const g of GUIONES) {
    const m = t.match(new RegExp('\\b' + g.toLowerCase() + '\\b'));
    if (m && m.index < pos) { mejor = g; pos = m.index; }
  }
  return mejor;
}

const anuncios = filas('Leer config_anuncios').filter(r => txt(r.ad_id));
let origen = txt(lead.origen).toUpperCase();
let origen_por = existe ? 'guardado' : '';
let ad_id = txt(lead.ad_id);
let ctwa_clid = txt(lead.ctwa_clid);
let anuncio_headline = txt(lead.anuncio_headline);

if (d.tiene_referral) {
  ad_id = d.ad_id || ad_id;
  ctwa_clid = d.ctwa_clid || ctwa_clid;
  anuncio_headline = d.anuncio_headline || anuncio_headline;
}

let detectado = '';
let detectado_por = '';
if (d.tiene_referral && d.ad_id) {
  const fila = anuncios.find(r => txt(r.ad_id) === d.ad_id && norm(r.activo) !== 'no');
  const g = fila ? txt(fila.guion).toUpperCase() : '';
  if (GUIONES.includes(g)) { detectado = g; detectado_por = 'referral'; }
}
if (!detectado && !existe) {
  const k = palabraClave(d.texto);
  if (k) { detectado = k; detectado_por = d.tiene_referral ? 'referral_sin_mapeo+palabra_clave' : 'palabra_clave'; }
}
// Primer contacto: se asigna. Lead existente: solo se mejora si estaba vacío o DIRECTO.
if (!existe) {
  origen = detectado || 'DIRECTO';
  origen_por = detectado_por || (d.tiene_referral ? 'referral_sin_mapeo' : 'sin_senal');
} else if (detectado && (!origen || origen === 'DIRECTO')) {
  origen = detectado;
  origen_por = detectado_por;
}
if (!origen) origen = 'DIRECTO';

// ---------------- ESTADO Y AGENTE ----------------
const estado = txt(lead.estado).toUpperCase() || 'NUEVO';
const recomendacion = txt(lead.recomendacion).toUpperCase();
const linkEnviado = Boolean(txt(lead.link_enviado_ts));
let agente;
if (!existe) agente = 'RECEPCIONISTA';
else if (recomendacion || ['LINK_ENVIADO', 'AGENDÓ', 'AGENDO'].includes(estado)) agente = 'CIERRE';
else agente = 'CALIFICADOR';

// ---------------- DISPONIBILIDAD ----------------
// Se lee en cada conversación de la hoja config_disponibilidad. Nunca fija en el prompt.
const disp = filas('Leer config_disponibilidad')[0] || {};
const entero = v => { const n = parseInt(String(v ?? '').replace(/[^0-9]/g, ''), 10); return Number.isFinite(n) && n > 0 ? n : 0; };
const oct = entero(disp.espacios_octubre);
const nov = entero(disp.espacios_noviembre);
const lugares = n => n === 1 ? '1 lugar' : n + ' lugares';
let frase_disponibilidad = '';
if (oct && nov) frase_disponibilidad = `Este mes solo abrimos ${lugares(oct)} para arrancar, y ${nov} para noviembre.`;
else if (oct) frase_disponibilidad = `Este mes solo abrimos ${lugares(oct)} para arrancar.`;
else if (nov) frase_disponibilidad = `Para noviembre solo abrimos ${lugares(nov)} para arrancar.`;

const yaMencionada = norm(lead.disponibilidad_mencionada) === 'si';
let instruccion_disponibilidad;
if (yaMencionada) instruccion_disponibilidad = 'Ya se mencionó en esta conversación. NO vuelvas a hablar de lugares disponibles.';
else if (frase_disponibilidad) instruccion_disponibilidad = 'Úsala UNA sola vez, en el mensaje donde haces la recomendación, con estas palabras: "' + frase_disponibilidad + '" Habla de "arrancar", nunca de "tenerlo todo listo".';
else instruccion_disponibilidad = 'No hay lugares que anunciar. NO uses escasez ni menciones lugares disponibles.';

// ---------------- DATOS FALTANTES ----------------
const v = k => txt(lead[k]);
const faltantes = [];
if (!v('especialidad') || !v('tipo_negocio')) faltantes.push('a) especialidad y tipo (consultorio, clínica u hospital)');
if (!v('ciudad')) faltantes.push('b) ciudad o zona');
if (!v('invierte_anuncios') || !v('presencia_digital')) faltantes.push('c) si invierte en anuncios y si tiene sitio web, Google Business o Doctoralia');
if (!v('quien_contesta')) faltantes.push('d) quién contesta el WhatsApp y cómo agendan');
if (!v('tratamiento_principal') || !v('ticket_aprox')) faltantes.push('e) tratamiento que más quiere vender y su precio aproximado');

const ORIGEN_DESC = {
  PACIENTES: 'anuncio PACIENTES (video de resultados de publicidad, caso Dr. Woolrich)',
  SISTEMA: 'anuncio SISTEMA (video del recorrido del sistema completo)',
  CUBETA: 'anuncio CUBETA (video "publicidad sin sistema es una cubeta con hoyos")',
  DIRECTO: 'DIRECTO (no llegó por un anuncio identificado)'
};
const o = s => s || '(sin dato)';
const fechaMX = new Date(Date.now() - 6 * 3600e3).toISOString().slice(0, 16).replace('T', ' ');

const contexto = [
  'CONTEXTO DE ESTA CONVERSACIÓN (lo genera el sistema; no lo cites textual)',
  'Fecha y hora CDMX: ' + fechaMX,
  'Primer mensaje del prospecto: ' + (existe ? 'no' : 'sí'),
  'ORIGEN: ' + origen + ' — ' + ORIGEN_DESC[origen] + (anuncio_headline ? ' | Título del anuncio: "' + anuncio_headline + '"' : ''),
  '',
  'DATOS DEL PROSPECTO (vacío = aún no lo sabemos):',
  '- Nombre: ' + o(v('nombre')),
  '- Especialidad: ' + o(v('especialidad')),
  '- Tipo de negocio: ' + o(v('tipo_negocio')),
  '- Ciudad o zona: ' + o(v('ciudad')),
  '- Invierte en anuncios: ' + o(v('invierte_anuncios')),
  '- Presencia digital: ' + o(v('presencia_digital')),
  '- Quién contesta y cómo agendan: ' + o(v('quien_contesta')),
  '- Tratamiento principal: ' + o(v('tratamiento_principal')),
  '- Precio aproximado del tratamiento: ' + (v('ticket_aprox') ? '$' + v('ticket_aprox') + ' MXN' : '(sin dato)'),
  '- Recomendación ya hecha: ' + o(recomendacion),
  '- Estado: ' + estado,
  '- Link de agenda ya enviado: ' + (linkEnviado ? 'sí' : 'no'),
  '',
  'PREGUNTAS DE CALIFICACIÓN PENDIENTES: ' + (faltantes.length ? faltantes.join('; ') : 'ninguna, ya tienes todo'),
  '',
  'DISPONIBILIDAD: ' + instruccion_disponibilidad
].join('\n');

return [{
  json: {
    wa_id: d.wa_id,
    telefono: d.telefono,
    nombre_perfil: d.nombre_perfil,
    phone_number_id: d.phone_number_id,
    message_id: d.message_id,
    texto: d.texto,
    es_media: d.es_media,
    tipo_mensaje: d.tipo_mensaje,
    ts_mensaje_ms: d.ts_mensaje_ms,
    existe,
    lead,
    agente,
    estado,
    origen,
    origen_por,
    ad_id,
    ctwa_clid,
    anuncio_headline,
    frase_disponibilidad,
    contexto
  }
}];

// GREEN CHIMP | SISTEMA PACIENTES — AUDIO, IMAGEN O STICKER SIN TEXTO
// No pasa por la IA: pide que lo escriba y deja el flujo igual que si contestara un agente.
const c = $('Contexto Lead').first().json;
const reply = c.existe
  ? 'Por aquí solo puedo leer mensajes de texto 🙏 ¿Me lo escribes?'
  : '¡Hola! Soy ChimpBot de Green Chimp 👋 Por aquí solo puedo leer mensajes de texto. ¿Me escribes tu duda o tu especialidad?';

return [{
  json: {
    output: JSON.stringify({ reply, captured: {}, recomendacion: '', flags: {} }),
    respuesta_fija: 'media'
  }
}];

// GREEN CHIMP | SISTEMA PACIENTES — PARSER DE SALIDA + REGLAS DEL REGISTRO
// 1) Lee el JSON del agente (o de "Respuesta Media").
// 2) Guardia: bloquea precios, promesas o nombres de plan que no están en la especificación.
// 3) Fusiona los datos capturados sin borrar lo que ya estaba.
// 4) Calcula estado, lead caliente y si se avisa a César por Telegram (una sola vez).

const c = $('Contexto Lead').first().json;
const lead = c.lead || {};
const raw = $input.first().json;

function txt(v) {
  if (v === null || v === undefined) return '';
  const r = String(v).trim();
  const b = r.toLowerCase();
  if (r === '' || r === '[null]' || b === 'null' || b === 'undefined') return '';
  return r;
}
const norm = s => txt(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const aBool = v => v === true || ['true', '1', 'si', 'yes'].includes(norm(v));

function parseJson(valor) {
  if (valor && typeof valor === 'object') {
    if (typeof valor.output === 'string' && !valor.reply) return parseJson(valor.output);
    return valor;
  }
  const s = txt(valor).replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  const i = s.indexOf('{'), f = s.lastIndexOf('}');
  if (i !== -1 && f > i) { try { return JSON.parse(s.slice(i, f + 1)); } catch (e) {} }
  return null;
}

const crudo = raw.output ?? raw.text ?? raw;
let out = parseJson(crudo);
if (!out || !txt(out.reply)) {
  // La IA contestó texto plano en lugar de JSON: se usa como respuesta si parece un mensaje.
  const plano = typeof crudo === 'string' ? txt(crudo) : '';
  out = { reply: plano && !plano.startsWith('{') ? plano : '', captured: {}, recomendacion: '', flags: {} };
}
const captured = (out.captured && typeof out.captured === 'object') ? out.captured : {};
const flags = (out.flags && typeof out.flags === 'object') ? out.flags : {};

// ---------------- GUARDIA DE SALIDA ----------------
let reply = txt(out.reply) || '¿Me cuentas un poco más? Así te digo qué te conviene.';
const LINK = 'https://greenchimpmx.com/contacto';

function montos(t) {
  const res = [];
  const re = /\$\s?(\d{1,3}(?:[,.]\d{3})+|\d+)(?:\s?(mil|k)\b)?/gi;
  let m;
  while ((m = re.exec(t))) {
    let n = Number(m[1].replace(/[,.](?=\d{3}\b)/g, ''));
    if (m[2]) n *= 1000;
    res.push(n);
  }
  const re2 = /(\d+(?:[.,]\d+)?)\s?mil\s?(pesos|mxn)/gi;
  while ((m = re2.exec(t))) res.push(Math.round(Number(m[1].replace(',', '.')) * 1000));
  return res;
}
const numerosDe = t => (txt(t).match(/\d[\d,.]*/g) || []).map(x => Number(x.replace(/[,.](?=\d{3}\b)/g, ''))).filter(Number.isFinite);

// Montos permitidos: los de la especificación + los que dio el propio prospecto.
const permitidos = new Set([6000, 35000, 981, 30000, 10, 15000]);
for (const n of numerosDe(c.texto)) { permitidos.add(n); if (n < 1000) permitidos.add(n * 1000); }
for (const n of numerosDe(lead.ticket_aprox)) permitidos.add(n);
for (const n of numerosDe(captured.ticket_aprox)) permitidos.add(n);

const r = norm(reply);
let guardia_motivo = '';
if (montos(reply).some(n => !permitidos.has(n))) guardia_motivo = 'precio_no_permitido';
else if (/garantiz|aseguramos que (vas|va) a|te prometo/.test(r)) guardia_motivo = 'promesa';
else if (/\b(plan|paquete|nivel)\s+(consultorio|clinica|ecosistema|salud|premium|pro|plus|gold|elite|esencial|profesional)\b/.test(r)) guardia_motivo = 'nombre_de_plan';
else if (/\b(vend(emos|e|er)|entreg(amos|a|ar)|compra(s|r)?)\s+(el|tu|un)\s+sistema\b/.test(r)) guardia_motivo = 'sistema_vendido';
else if (/auditoria de fugas|permanencia|descuento|prompt|n8n|manychat|openai/.test(r)) guardia_motivo = 'termino_no_permitido';

if (guardia_motivo === 'precio_no_permitido' || guardia_motivo === 'nombre_de_plan') {
  reply = 'Los planes van desde $6,000 hasta $35,000 MXN al mes, y la pauta publicitaria va aparte (la pagas directo a las plataformas). El plan exacto lo armamos en una llamada de 20 min con César según tu especialidad y zona. ¿Te paso el link para agendar?';
} else if (guardia_motivo === 'termino_no_permitido') {
  reply = 'Eso lo vemos con detalle en la llamada de 20 min con César, para darte información exacta de tu caso. ¿Te paso el link para agendar?';
} else if (guardia_motivo) {
  reply = 'No prometemos un número de pacientes; lo que sí hacemos es medir cada paso, desde el anuncio hasta la consulta. En una llamada de 20 min con César te enseño cómo funcionaría en tu caso. ¿Te paso el link para agendar?';
}
if (reply.length > 1200) reply = reply.slice(0, 1197).replace(/\s+\S*$/, '') + '...';

// ---------------- FUSIÓN DE DATOS (nunca se borra con vacío) ----------------
function tipoNegocio(v) {
  const t = norm(v);
  if (!t) return '';
  if (t.includes('hospital')) return 'HOSPITAL';
  if (t.includes('clinica')) return 'CLÍNICA';
  if (t.includes('consultorio') || t.includes('individual')) return 'CONSULTORIO';
  return '';
}
function siNo(v) {
  const t = norm(v);
  if (!t) return '';
  if (/^(si|yes|true)\b/.test(t)) return 'sí';
  if (/^(no|false)\b/.test(t)) return 'no';
  return '';
}
function ticket(v) {
  const t = norm(v);
  if (!t) return '';
  let n = Number((t.match(/\d[\d,.]*/) || [''])[0].replace(/[,.](?=\d{3}\b)/g, ''));
  if (!Number.isFinite(n) || n <= 0) return '';
  if (/\bmil\b|\bk\b/.test(t) && n < 1000) n *= 1000;
  return String(Math.round(n));
}
function recom(v) {
  const t = norm(v);
  if (t.startsWith('basic')) return 'BÁSICO';
  if (t.startsWith('complet')) return 'COMPLETO';
  if (t.startsWith('intermed')) return 'INTERMEDIO';
  return '';
}

const nuevo = {
  nombre: txt(captured.nombre),
  especialidad: txt(captured.especialidad),
  tipo_negocio: tipoNegocio(captured.tipo_negocio),
  ciudad: txt(captured.ciudad),
  invierte_anuncios: siNo(captured.invierte_anuncios),
  presencia_digital: txt(captured.presencia_digital),
  quien_contesta: txt(captured.quien_contesta),
  tratamiento_principal: txt(captured.tratamiento_principal),
  ticket_aprox: ticket(captured.ticket_aprox)
};
const campo = k => nuevo[k] || txt(lead[k]);

const recomendacion = recom(out.recomendacion) || recom(lead.recomendacion);

// ---------------- FECHAS (CDMX = UTC-6, sin horario de verano) ----------------
const isoMX = ms => new Date(ms - 6 * 3600e3).toISOString().slice(0, 19) + '-06:00';
const ahoraMs = Date.now();
const ahora = isoMX(ahoraMs);

// ---------------- ESTADO ----------------
const RANGO = { NUEVO: 0, CALIFICADO: 1, LINK_ENVIADO: 2, 'AGENDÓ': 3 };
let estado = txt(lead.estado).toUpperCase().replace('AGENDO', 'AGENDÓ');
if (!(estado in RANGO)) estado = 'NUEVO'; // FRÍO u otro valor: el prospecto volvió a escribir
const subir = e => { if (RANGO[e] > RANGO[estado]) estado = e; };

const linkEnEsteMensaje = reply.includes('greenchimpmx.com/contacto');
const link_enviado_ts = linkEnEsteMensaje ? ahora : txt(lead.link_enviado_ts);
if (recomendacion) subir('CALIFICADO');
if (link_enviado_ts) subir('LINK_ENVIADO');
if (aBool(flags.agendo)) subir('AGENDÓ');
if (aBool(flags.no_interesado) && estado !== 'AGENDÓ') estado = 'FRÍO';

// ---------------- LEAD CALIENTE (al menos 2 de 5) ----------------
const pidio_precio_demo = aBool(flags.pidio_precio_o_demo) || norm(lead.pidio_precio_demo) === 'si';
const acepto_llamada = aBool(flags.acepto_llamada) || norm(lead.acepto_llamada) === 'si' || estado === 'AGENDÓ';
const criterios = [];
if (['CLÍNICA', 'HOSPITAL'].includes(campo('tipo_negocio'))) criterios.push('clínica u hospital');
if (campo('invierte_anuncios') === 'sí') criterios.push('ya invierte en anuncios');
if (Number(campo('ticket_aprox')) > 15000) criterios.push('tratamiento > $15,000');
if (pidio_precio_demo) criterios.push('pidió precio o demo');
if (acepto_llamada) criterios.push('aceptó la llamada');
const lead_caliente = criterios.length >= 2;

const avisoPrevio = txt(lead.aviso_telegram_ts);
const enviar_aviso = lead_caliente && !avisoPrevio;

const disponibilidad_mencionada = norm(lead.disponibilidad_mencionada) === 'si'
  || aBool(flags.menciono_disponibilidad)
  || Boolean(c.frase_disponibilidad && /abrimos \d+ lugar/.test(reply));

// ---------------- FILA PARA LA HOJA "leads" ----------------
const fila = {
  fecha: txt(lead.fecha) || ahora.slice(0, 16).replace('T', ' '),
  nombre: campo('nombre') || c.nombre_perfil,
  telefono: c.telefono,
  wa_id: c.wa_id,
  origen: c.origen,
  ad_id: c.ad_id,
  ctwa_clid: c.ctwa_clid,
  especialidad: campo('especialidad'),
  tipo_negocio: campo('tipo_negocio'),
  ciudad: campo('ciudad'),
  invierte_anuncios: campo('invierte_anuncios'),
  presencia_digital: campo('presencia_digital'),
  quien_contesta: campo('quien_contesta'),
  tratamiento_principal: campo('tratamiento_principal'),
  ticket_aprox: campo('ticket_aprox'),
  recomendacion,
  estado,
  lead_caliente: lead_caliente ? 'sí' : 'no',
  ultimo_mensaje_ts: isoMX(c.ts_mensaje_ms || ahoraMs),
  anuncio_headline: c.anuncio_headline,
  origen_detectado_por: c.origen_por,
  pidio_precio_demo: pidio_precio_demo ? 'sí' : 'no',
  acepto_llamada: acepto_llamada ? 'sí' : 'no',
  disponibilidad_mencionada: disponibilidad_mencionada ? 'sí' : 'no',
  link_enviado_ts,
  seguimiento_nivel: '0', // respondió: se reinicia el seguimiento
  ultimo_seguimiento_ts: txt(lead.ultimo_seguimiento_ts),
  aviso_telegram_ts: enviar_aviso ? ahora : avisoPrevio,
  ultimo_bot_ts: ahora,
  phone_number_id: c.phone_number_id,
  ultimo_mensaje: txt(c.texto).slice(0, 300),
  ultima_respuesta_bot: reply.slice(0, 300)
};

return [{
  json: {
    wa_id: c.wa_id,
    phone_number_id: c.phone_number_id,
    reply,
    agente: raw.respuesta_fija ? 'RESPUESTA_FIJA_' + String(raw.respuesta_fija).toUpperCase() : c.agente,
    guardia_motivo,
    enviar_aviso,
