const p = $('Parser Salida').first().json;
const ultimo = Date.parse(p.fila.ultimo_mensaje_ts);
const horas = Number.isFinite(ultimo) ? (Date.now() - ultimo) / 3600e3 : 0;
let texto = String(p.reply || '').trim();
if (texto.length > 4096) texto = texto.slice(0, 4093) + '...';

return [{
