    horas_desde_ultimo_mensaje: Math.round(horas * 100) / 100,
    ventana_abierta: horas < 24 && texto !== ''
  }
}];

// GREEN CHIMP | SISTEMA PACIENTES — AVISO DE LEAD CALIENTE PARA CÉSAR
const p = $('Parser Salida').first().json;
const f = p.fila;
const v = x => String(x ?? '').trim() || '—';
const ticket = Number(f.ticket_aprox) > 0 ? ' (~$' + Number(f.ticket_aprox).toLocaleString('en-US') + ')' : '';

const texto =
  '🔥 LEAD CALIENTE — Sistema de Pacientes\n\n' +
  'Nombre: ' + v(f.nombre) + '\n' +
  'Teléfono: ' + v(f.telefono) + '\n' +
  'Especialidad: ' + v(f.especialidad) + ' · ' + v(f.tipo_negocio) + '\n' +
  'Ciudad: ' + v(f.ciudad) + '\n' +
  'Origen: ' + v(f.origen) + (f.ad_id ? ' (ad_id ' + f.ad_id + ')' : '') + (f.anuncio_headline ? ' — "' + f.anuncio_headline + '"' : '') + '\n\n' +
  'CALIFICACIÓN\n' +
  '• Invierte en anuncios: ' + v(f.invierte_anuncios) + '\n' +
