return [{ json: { texto } }];

// GREEN CHIMP | SISTEMA PACIENTES — SEGUIMIENTO (corre cada 15 min)
// Nunca más de 3 mensajes seguidos sin respuesta del prospecto:
//   NUEVO / CALIFICADO : respuesta del bot + texto a las 4 h + texto a las 23 h → FRÍO al vencer las 24 h.
//   LINK_ENVIADO       : link + texto a las 4 h (mismo día) + recordatorio al día siguiente → FRÍO.
//                        El recordatorio va como texto si la ventana sigue abierta; si no, con la
//                        plantilla aprobada por Meta.
// Si el prospecto responde, el flujo de entrada reinicia seguimiento_nivel a 0.
// Horario de envío: 8:00 a 21:59 CDMX.

const PLANTILLA = { nombre: 'gc_sp_recordatorio_llamada', idioma: 'es_MX' };
const LINK = 'https://greenchimpmx.com/contacto';

const txt = v => String(v ?? '').trim();
const norm = s => txt(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const H = 3600e3;
const ahoraMs = Date.now();
const mx = ms => new Date(ms - 6 * H); // CDMX = UTC-6 (sin horario de verano)
const isoMX = ms => mx(ms).toISOString().slice(0, 19) + '-06:00';
const diaMX = ms => mx(ms).toISOString().slice(0, 10);
const horaMX = mx(ahoraMs).getUTCHours();
const enHorario = horaMX >= 8 && horaMX < 22;
const hoy = diaMX(ahoraMs);

const pausados = new Set();
try {
  for (const i of $('Leer pausados').all()) {
    if (i.json && i.json.wa_id) pausados.add(String(i.json.phone_number_id) + '|' + String(i.json.wa_id));
  }
} catch (e) {}

const salida = [];
const vistos = new Set();

for (const item of $('Leer leads').all()) {
  const r = item.json || {};
  const wa_id = txt(r.wa_id);
  if (!wa_id || vistos.has(wa_id)) continue;
  vistos.add(wa_id);

  const estado = txt(r.estado).toUpperCase();
  if (!['NUEVO', 'CALIFICADO', 'LINK_ENVIADO'].includes(estado)) continue; // FRÍO, AGENDÓ o vacío
  if (pausados.has(txt(r.phone_number_id) + '|' + wa_id)) continue;        // lo atiende una persona
  if (!txt(r.phone_number_id)) continue;

  const ultimo = Date.parse(txt(r.ultimo_mensaje_ts));
  if (!Number.isFinite(ultimo)) continue;
  const horas = (ahoraMs - ultimo) / H;
  const nivel = parseInt(txt(r.seguimiento_nivel), 10) || 0;

  const nombre = txt(r.nombre).split(/\s+/)[0];
  const hola = nombre ? 'Hola ' + nombre : 'Hola';
  const esp = txt(r.especialidad);
  const base = { wa_id, phone_number_id: txt(r.phone_number_id), nombre_param: nombre || 'doctor(a)' };

  if (estado !== 'LINK_ENVIADO') {
    if (horas >= 24) {
      salida.push({ json: { ...base, accion: 'frio', estado_nuevo: 'FRÍO', nivel_nuevo: String(nivel) } });
    } else if (enHorario && horas >= 23 && nivel < 2) {
      const texto = hola + ', te escribo una última vez para no llenarte de mensajes. Si quieres ver qué tendría sentido para ' +
        (esp ? 'tu consulta de ' + esp.toLowerCase() : 'tu consultorio o clínica') +
        ', lo platicamos en una llamada de 20 min con César. ¿Te paso el link?';
      salida.push({ json: { ...base, accion: 'enviar', tipo: 'texto', texto, estado_nuevo: estado, nivel_nuevo: '2' } });
    } else if (enHorario && horas >= 4 && horas < 23 && nivel < 1) {
      let texto;
      if (!esp) texto = hola + ' 👋 Me quedé pendiente: ¿cuál es tu especialidad? Con eso te digo qué tendría más sentido para ti.';
      else if (!txt(r.recomendacion)) texto = hola + ', me quedé con lo de tu consulta de ' + esp.toLowerCase() + '. ¿Seguimos? Con un par de datos más te digo si te conviene algo básico o el sistema completo.';
      else texto = hola + ' 👋 ¿Te quedó alguna duda de lo que platicamos? Si quieres, lo vemos en una llamada de 20 min con César. ¿Te paso el link para agendar?';
      salida.push({ json: { ...base, accion: 'enviar', tipo: 'texto', texto, estado_nuevo: estado, nivel_nuevo: '1' } });
    }
    continue;
  }

  // LINK_ENVIADO
  const linkMs = Date.parse(txt(r.link_enviado_ts)) || ultimo;
  const diaLink = diaMX(linkMs);
  const ultSeg = Date.parse(txt(r.ultimo_seguimiento_ts));
  if (nivel >= 2) {
    if (Number.isFinite(ultSeg) && ahoraMs - ultSeg >= 24 * H) {
      salida.push({ json: { ...base, accion: 'frio', estado_nuevo: 'FRÍO', nivel_nuevo: String(nivel) } });
    }
    continue;
  }
  if (ahoraMs - Math.max(linkMs, ultimo) > 72 * H) {
    // El recordatorio no alcanzó a salir (fin de semana, horario): no se insiste más.
    salida.push({ json: { ...base, accion: 'frio', estado_nuevo: 'FRÍO', nivel_nuevo: String(nivel) } });
    continue;
  }
  if (hoy > diaLink) {
    // Recordatorio del día siguiente (de 10:00 en adelante).
    if (horaMX >= 10 && horaMX < 21) {
      if (horas < 23.5) {
        const texto = hola + ', buen día. ¿Te aparto un espacio para la llamada de diagnóstico con César? Agendas aquí en un minuto: ' + LINK + ' (calendario "AGENDA UNA LLAMADA").';
        salida.push({ json: { ...base, accion: 'enviar', tipo: 'texto', texto, estado_nuevo: estado, nivel_nuevo: '2' } });
      } else {
        salida.push({ json: { ...base, accion: 'enviar', tipo: 'plantilla', plantilla: PLANTILLA.nombre, idioma: PLANTILLA.idioma,
          texto: '[plantilla ' + PLANTILLA.nombre + ']', estado_nuevo: estado, nivel_nuevo: '2' } });
      }
    }
  } else if (enHorario && horas >= 4 && horas < 23 && nivel < 1) {
    const texto = hola + ' 👋 ¿Pudiste ver el calendario? Te dejo el link otra vez: ' + LINK + ' → "AGENDA UNA LLAMADA". Son 20 min con César.';
    salida.push({ json: { ...base, accion: 'enviar', tipo: 'texto', texto, estado_nuevo: estado, nivel_nuevo: '1' } });
  }
}

const ts = isoMX(ahoraMs);
return salida.map(i => ({ json: { ...i.json, ts } }));

